from decimal import Decimal

from pydantic import BaseModel, ConfigDict, Field

from app.models.enums import EquipmentStatus


# Define core fields and validation (Base Model for Equipment class)
class EquipmentBase(BaseModel):
    # id: int
    # serial_number: string(50)
    # model: string(100)
    # status: enum(EquipmentStatus)
    # fuel_level: numeric(0-100)
    # farm_id: int (foreign key, farm)

    # note: id autogenerated by db
    serial_number: str = Field(min_length=1, max_length=50) # Pydantic would autoreject strings outside constraints)
    model: str = Field(min_length=1, max_length=100)
    status: EquipmentStatus = EquipmentStatus.IDLE
    fuel_level: Decimal = Field(ge=0, le=100) # greater than or equal to, less than or equal to
    farm_id: int

class EquipmentCreate(EquipmentBase):
    pass # Would inherit every field/constraint from the EquipmentBase

class EquipmentRead(EquipmentBase):
    id: int
    model_config = ConfigDict(from_attributes=True)

# Typical Classes in Schema Files:
# ModelBase
# ModelCreate
# ModelRead
# ModelUpdate
# ModelDelete

# Note: It seems any creation into the database doesn't require the id, just the info
# But if you're doing anything that requires the id (reading, updating), perhaps include it?
# Eg. Incoming CREATE Request: no id required, will be generated by the db
# EquipmentCreate validates input
# EquipmentRead, reads attributes from ORM, include id into json output

